const x=$json,t=String(x.text??"").toLowerCase(); let intent="off_topic";
if(/panier|cart/.test(t)&&/zid|add|ajout/.test(t)) intent="cart_add";
else if(/gadech|قداش|prix|price|souma/.test(t)) intent="pricing";
else if(/promo|promotion|discount|remise/.test(t)) intent="promotion";
else if(/livraison|delivery/.test(t)) intent="shipping";
else if(/commande|order/.test(t)&&/status|win|وين|فين/.test(t)) intent="order_status";
else if(/catalog|catalogue|chnowa|شنوة|what.*have/.test(t)) intent="product_discovery";
return [{json:{...x,intent:{name:intent,confidence:null,route:["pricing","promotion","shipping","order_status"].includes(intent)?"support":"sales"}}}];
